import os

for d in ["proj/src/pkg", "proj/.git/objects", "proj/docs"]:
    os.makedirs(d)
for f in ["proj/src/pkg/a.py", "proj/src/b.py", "proj/docs/x.md", "proj/.git/HEAD"]:
    open(f, "w").close()

py_files = []
for dirpath, dirnames, filenames in os.walk("proj"):
    dirnames[:] = sorted(d for d in dirnames if not d.startswith("."))
    for name in filenames:
        if name.endswith(".py"):
            py_files.append(os.path.join(dirpath, name))
print(sorted(py_files))  # ['proj/src/b.py', 'proj/src/pkg/a.py']

# bottom-up: children first, so empty dirs can be removed safely
order = [p for p, _, _ in os.walk("proj/src", topdown=False)]
print(order)             # ['proj/src/pkg', 'proj/src']

import os

os.makedirs("logs/archive")
for name, size in [("app.log", 120), ("err.log", 30)]:
    with open(os.path.join("logs", name), "w") as f:
        f.write("x" * size)

def files_under(path):
    with os.scandir(path) as it:
        for entry in it:
            if entry.is_dir(follow_symlinks=False):
                yield from files_under(entry.path)
            elif entry.is_file():
                yield entry

total = sum(e.stat().st_size for e in files_under("logs"))
print(total)                                     # 150
print(sorted(e.name for e in files_under("logs")))  # ['app.log', 'err.log']
